fields.InputDefinition:
{
  "goal": "Open the Chat application and wait for the workspace. Select the conversation named 'Membership renewal questions' from the sidebar — it is seeded with a completed AI reply as its last message. Do NOT send any message: this environment has no AI model, so a new reply will not arrive. Under that AI reply, confirm its action row renders: a 'Regenerate' button, a 'Rate response' button (speech-bubble icon) and a pin (thumbtack) button with the tooltip 'Pin message'; a trash-can delete button may also appear. Do NOT click 'Regenerate' or the trash can. Click 'Rate response' and confirm a 'Rate this response' dialog opens with numbered buttons 1 to 10, '1 — Worst' / '10 — Best' labels and a 'Tell us more' box, then close it with Cancel (do NOT submit). Click the pin button and confirm it turns highlighted (tooltip 'Unpin message') and/or a thumbtack chip with a count appears in the conversation header; then click the pin button again to unpin it. Seeing the message action controls render and the pin toggle respond is success. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
